    (function(){
    const CHARACTERS = [
      { name:'', img:"data:image/webp;base64,", ring:'#c9a961' },
      { name:'', img:"data:image/webp;base64,", ring:'#79c48f' },
      { name:'', img:"data:image/webp;base64,", ring:'#e8c777' },
      { name:'', img:"data:image/webp;base64,", ring:'#d97757' },
      { name:'', img:"data:image/webp;base64,", ring:'#8ea7d9' },
      { name:'', img:"data:image/png;base64,", ring:'#c98ed9' },
    ];
  
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const startScreen = document.getElementById('startScreen');
    const gameOverScreen = document.getElementById('gameOverScreen');
    const skinRow = document.getElementById('skinRow');
    const playBtn = document.getElementById('playBtn');
    const retryBtn = document.getElementById('retryBtn');
    const changeSkinBtn = document.getElementById('changeSkinBtn');
    const massPanel = document.getElementById('massPanel');
    const leaderboardEl = document.getElementById('leaderboard');
    const leaderboardList = document.getElementById('leaderboardList');
    const hint = document.getElementById('hint');
    const finalMassEl = document.getElementById('finalMass');
    const minimapWrap = document.getElementById('minimapWrap');
    const minimap = document.getElementById('minimap');
    const mctx = minimap.getContext('2d');
    const boostBtn = document.getElementById('boostBtn');
    const ejectBtn = document.getElementById('ejectBtn');
  
    let boostTimer = 0, boostDirX = 0, boostDirY = 1;
    const BOOST_COST = 9, BOOST_MIN_MASS = 30, BOOST_DURATION = 0.28, BOOST_SPEED_MULT = 2.4;
  
    
    let audioCtx = null;
    function ensureAudio(){
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      else if (audioCtx.state === 'suspended') audioCtx.resume();
    }
    function beep(freqStart, freqEnd, duration, type, volume){
      if (!audioCtx) return;
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = type || 'sine';
      osc.frequency.setValueAtTime(freqStart, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(Math.max(freqEnd,1), audioCtx.currentTime + duration);
      gain.gain.setValueAtTime(volume || 0.15, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
      osc.connect(gain); gain.connect(audioCtx.destination);
      osc.start(); osc.stop(audioCtx.currentTime + duration);
    }
    function sfxEat(){
      if (!audioCtx) return;
      beep(430, 760, 0.07, 'sine', 0.075);
      setTimeout(()=>beep(760, 980, 0.045, 'sine', 0.045), 28);
    }
    function sfxAbsorb(){
      if (!audioCtx) return;
      beep(180, 62, 0.32, 'sawtooth', 0.11);
      setTimeout(()=>beep(520, 180, 0.18, 'triangle', 0.07), 35);
    }
    function sfxBoost(){
      if (!audioCtx) return;
      beep(150, 720, 0.18, 'sawtooth', 0.09);
      setTimeout(()=>beep(720, 1150, 0.10, 'square', 0.045), 35);
    }
    function sfxSplit(){
      if (!audioCtx) return;
      beep(520, 900, 0.09, 'square', 0.08);
      setTimeout(()=>beep(900, 620, 0.06, 'square', 0.04), 30);
    }
    function sfxEject(){
      if (!audioCtx) return;
      beep(320, 210, 0.08, 'triangle', 0.06);
    }
    function sfxVirus(){
      if (!audioCtx) return;
      beep(90, 40, 0.4, 'sawtooth', 0.14);
      setTimeout(()=>beep(300,120,0.2,'square',0.06), 60);
    }
    function sfxGameOver(){
      if (!audioCtx) return;
      beep(420, 180, 0.22, 'sine', 0.10);
      setTimeout(()=>beep(250, 75, 0.65, 'triangle', 0.13), 170);
    }
    function sfxStart(){
      if (!audioCtx) return;
      beep(260, 520, 0.10, 'sine', 0.06);
      setTimeout(()=>beep(520, 880, 0.12, 'sine', 0.07), 80);
    }
    function sfxClick(){
      if (!audioCtx) return;
      beep(600, 760, 0.055, 'square', 0.045);
    }
  
    function resize(){ canvas.width = window.innerWidth; canvas.height = window.innerHeight; }
    window.addEventListener('resize', resize);
    resize();
  
    function loadImage(src){
      return new Promise(resolve => { const img = new Image(); img.onload = () => resolve(img); img.src = src; });
    }
  
    // Recorte [x, y, lado] de cada personaje (en píxeles de su imagen) para que la cara llene todo el círculo
    const PORTRAIT_CROPS = [
      [105, 80, 300],
      [110, 100, 290],
      [115, 262, 225],
      [170, 55, 230],
      [145, 25, 190],
      [28, 35, 130]
    ];

    function circularCanvas(img, size, crop){
      const c = document.createElement('canvas');
      c.width = size; c.height = size;
      const cx = c.getContext('2d');
      const r = size/2;
      cx.save();
      cx.beginPath(); cx.arc(r,r,r,0,Math.PI*2); cx.closePath(); cx.clip();
      cx.fillStyle = '#2b2f3a';
      cx.fillRect(0,0,size,size);
      if (crop) {
        cx.drawImage(img, crop[0], crop[1], crop[2], crop[2], 0, 0, size, size);
      } else {
        const scale = Math.max(size/img.width, size/img.height);
        const w = img.width*scale, h = img.height*scale;
        cx.drawImage(img, r-w/2, r-h/2, w, h);
      }
      cx.restore();
      return c;
    }
  
    let portraits = [];
    let selectedSkin = null;
  
  
    const WORLD = 7600;             
    const FOOD_COUNT = 4500;         
    const BOT_COUNT = 80;            
    const VIRUS_COUNT = 16;         
    const MAX_CELLS = 12;           
    const MIN_SPLIT_MASS = 36;       
    const SPLIT_SPEED = 860;        
    const IMPULSE_DRAG = 3.6;       
    const RECOMBINE_BASE = 11;      
    const EJECT_COST = 18;          
    const EJECT_MASS = 13;          
    const EJECT_SPEED = 620;         
    const VIRUS_POP_MASS = 132;      
    const VIRUS_RADIUS = 52;         
    const VIRUS_FEED_LIMIT = 7;      
    const BOT_VIEW = 560;           
    const MOVING_ORB_COUNT = 14;       
    const MOVING_ORB_RADIUS = 9;      
    const MOVING_ORB_SPEED = 92;     
    const MOVING_ORB_POINTS = 20;
    const MOVING_ORB_GROW_START = 180000; 
    const MOVING_ORB_GROW_FULL = 900000;  
    const MOVING_ORB_MAX_RADIUS = 42;
    const MOVING_ORB_EVADE_RANGE = 380;
    const MOVING_ORB_EVADE_COOLDOWN = 2.2;
    const DAMAGE_RATIO = 0.34;        
    const DAMAGE_MIN_MASS = 7;      
    const DROP_MASS = 8;              
    const MAX_DROPS = 260;
    const BOT_NAMES = [
      'Alex','Daniel','Mateo','Lucas','Leo','Santiago','Diego','Adrian','Nicolas','Gabriel',
      'Samuel','David','Carlos','Miguel','Andres','Javier','Martin','Pablo','Luis','Marco',
      'Julian','Bruno','Emilio','Victor','Ivan','Rafael','Tomas','Enzo','Dylan','Noah',
      'Ethan','Oliver','Liam','Mia','Sofia','Emma','Valentina','Camila','Laura','Elena',
      'Sara','Ana','Julia','Clara','Paula','Maria','Isabella','Lucia','Daniela','Natalia',
      'Marta','Carla','Alicia','Irene','Nora','Vera','Alma','Lola','Eva','Rocio'
    ];
  
    let player, bots = [], food = [], viruses = [], ejects = [], movingOrbs = [], massDrops = [];
    let running = false;
    let gameStartTime = performance.now();
    let pointerX = null, pointerY = null;
  
    const mpToggle = document.getElementById('mpToggle');
    const mpFields = document.getElementById('mpFields');
    const mpServerUrl = document.getElementById('mpServerUrl');
    const mpRoomCode = document.getElementById('mpRoomCode');
    const mpCreateBtn = document.getElementById('mpCreateBtn');
    const mpJoinBtn = document.getElementById('mpJoinBtn');
    const mpStatus = document.getElementById('mpStatus');
    const roomPanel = document.getElementById('roomPanel');
  
    let mpSocket = null;
    let mpConnected = false;
    let mpId = null;
    let mpRoom = null;
    const remotePlayers = new Map();
    let lastStateSentAt = 0;
    let lastPhotoSent = 0;
    const STATE_SEND_INTERVAL = 90;
    const REMOTE_TIMEOUT = 6000;
  
    mpToggle.addEventListener('change', () => {
      mpFields.classList.toggle('show', mpToggle.checked);
      playBtn.disabled = true;
    });
  
    function mpSetStatus(text, kind){
      mpStatus.textContent = text;
      mpStatus.className = 'mp-status' + (kind ? ' ' + kind : '');

    }
  
    let pendingStart = false;
    function mpReset(){
      const old = mpSocket;
      clearTimeout(mpRetryTimer);
      mpSocket = null; mpConnected = false; mpRoom = null; pendingStart = false;
      if (old) { try { old.close(); } catch(_) {} }
      mpRoomCode.value = '';
      mpSetStatus('');
    }

    function mpWake(){
      try {
        const u = mpServerUrl.value.trim().replace(/^wss:/,'https:').replace(/^ws:/,'http:');
        if (u) fetch(u, { mode:'no-cors', cache:'no-store' }).catch(()=>{});
      } catch(_) {}
    }

    const MP_MAX_TRIES = 6;
    let mpRetryTimer = null;

    function mpOpenSocket(onOpenSend, attempt){
      attempt = attempt || 1;
      clearTimeout(mpRetryTimer);
      const url = mpServerUrl.value.trim();
      if (!url) { mpSetStatus('Escribe la dirección del servidor.', 'err'); pendingStart = false; return; }
      if (mpSocket) { const old = mpSocket; mpSocket = null; try { old.close(); } catch(_) {} }
      mpConnected = false;
      let sock;
      try {
        sock = new WebSocket(url);
      } catch (err) {
        mpSetStatus('No se pudo conectar: ' + err.message, 'err');
        pendingStart = false;
        return;
      }
      mpSocket = sock;
      let joined = false, answered = false, lastCode = '';
      mpSetStatus(attempt === 1
        ? 'Conectando... (si el servidor estaba dormido puede tardar hasta 1 minuto)'
        : 'El servidor está despertando... intento ' + attempt + ' de ' + MP_MAX_TRIES);
      const failTimer = setTimeout(() => { if (!joined && sock === mpSocket) { try { sock.close(); } catch(_) {} } }, 20000);
      const retryOrFail = () => {
        clearTimeout(failTimer);
        if (sock !== mpSocket || joined || answered) return;
        mpConnected = false;
        if (attempt < MP_MAX_TRIES) {
          mpSetStatus('Sin respuesta aún (intento ' + attempt + ' de ' + MP_MAX_TRIES + '). Reintentando...');
          mpRetryTimer = setTimeout(() => mpOpenSocket(onOpenSend, attempt + 1), 3000);
        } else {
          pendingStart = false;
          mpSetStatus('No se pudo conectar con ' + url + (lastCode ? ' (código ' + lastCode + ')' : '') + '. Revisa en Render que el servicio esté "Live" y vuelve a tocar el botón.', 'err');
        }
      };
      sock.addEventListener('open', () => {
        if (sock !== mpSocket) return;
        sock.send(JSON.stringify(onOpenSend));
      });
      sock.addEventListener('message', (ev) => {
        if (sock !== mpSocket) return;
        let msg;
        try { msg = JSON.parse(ev.data); } catch { return; }
        if (msg.type === 'joined') { joined = true; clearTimeout(failTimer); }
        if (msg.type === 'error') { answered = true; clearTimeout(failTimer); }
        mpHandleMessage(msg);
      });
      sock.addEventListener('close', (ev) => {
        if (sock !== mpSocket) return;
        lastCode = ev && ev.code ? ev.code : lastCode;
        if (!joined && answered) return;
        if (!joined) { retryOrFail(); return; }
        mpConnected = false; pendingStart = false;
        mpSetStatus('Conexión cerrada.', 'err');
      });
      sock.addEventListener('error', () => {
        if (sock !== mpSocket) return;
        if (!joined && answered) return;
        if (!joined) { retryOrFail(); return; }
        pendingStart = false;
        mpSetStatus('Error de conexión con el servidor.', 'err');
      });
    }

    function mpHandleMessage(msg){
      if (msg.type === 'joined') {
        mpConnected = true;
        mpId = msg.id;
        mpRoom = msg.code;
        mpSetStatus('Conectado. Código de sala: ' + mpRoom, 'ok');
        roomPanel.textContent = 'Sala: ' + mpRoom;
        mpRoomCode.value = mpRoom;
        if (pendingStart) { pendingStart = false; sfxStart(); startGame(); }
        return;
      }
      if (msg.type === 'error') {
        pendingStart = false;
        mpSetStatus(msg.message || 'Error', 'err');
        return;
      }
      if (msg.type === 'leave') {
        remotePlayers.delete(msg.id);
        return;
      }
      if (msg.type === 'state') {
        if (!running) return;
        let rp = remotePlayers.get(msg.id);
        if (!rp) {
          const remoteCustom = msg.char === -1;
          const ci = Math.max(0, Math.min(CHARACTERS.length - 1, remoteCustom ? 0 : (msg.char || 0)));
          rp = { char: ci, ring: remoteCustom ? '#ffffff' : CHARACTERS[ci].ring, portrait: remoteCustom ? getBlankPortrait() : portraits[ci] };
          remotePlayers.set(msg.id, rp);
        }
        if (typeof msg.photo === 'string' && msg.photo !== rp.photoSrc && msg.photo.length < 60000 &&
            /^data:image\/jpeg;base64,[A-Za-z0-9+\/=]+$/.test(msg.photo)) {
          rp.photoSrc = msg.photo;
          loadImage(msg.photo).then(im => { rp.portrait = circularCanvas(im, 128); });
        }
        rp.x = msg.x; rp.y = msg.y; rp.mass = msg.mass;
        rp.name = msg.name || 'Rival';
        rp.last = performance.now();
        return;
      }
      if (msg.type === 'eat') {
        if (msg.target === mpId && running) {
          player.cells.forEach(c => c.mass = 0);
          player.cells = [];
          endGame();
        }
        return;
      }
    }
  
    mpCreateBtn.addEventListener('click', () => {
      pendingStart = false;
      mpOpenSocket({ type: 'create' });
    });
    mpJoinBtn.addEventListener('click', () => {
      pendingStart = false;
      const code = mpRoomCode.value.trim().toUpperCase();
      if (!code) { mpSetStatus('Escribe el código de la sala.', 'err'); return; }
      mpOpenSocket({ type: 'join', code });
    });
  
    function mpSendState(){
      if (!mpConnected || !mpSocket || mpSocket.readyState !== WebSocket.OPEN) return;
      const now = performance.now();
      if (now - lastStateSentAt < STATE_SEND_INTERVAL) return;
      lastStateSentAt = now;
      const cen = playerCentroid();
      const isCustom = selectedSkin === 'custom' && !!customSmallURL;
      const payload = {
        type: 'state',
        x: cen.x, y: cen.y, mass: playerMass(),
        char: isCustom ? -1 : (selectedSkin === 'custom' ? 0 : selectedSkin), name: player.name
      };
      if (isCustom && now - lastPhotoSent > 4000){ payload.photo = customSmallURL; lastPhotoSent = now; }
      mpSocket.send(JSON.stringify(payload));
    }
  
    function mpSendEat(targetId){
      if (!mpConnected || !mpSocket || mpSocket.readyState !== WebSocket.OPEN) return;
      mpSocket.send(JSON.stringify({ type: 'eat', target: targetId }));
    }
  
    function mpPruneStale(){
      const now = performance.now();
      remotePlayers.forEach((rp, id) => {
        if (now - rp.last > REMOTE_TIMEOUT) remotePlayers.delete(id);
      });
    }
  
    window.addEventListener('pointermove', e => {
      pointerX = e.clientX; pointerY = e.clientY;
    });
    window.addEventListener('pointerdown', e => {
      pointerX = e.clientX; pointerY = e.clientY;
    });
  
    function randRange(a,b){ return a + Math.random()*(b-a); }
  
    function makeBlob(charIndex, x, y, mass){
      return {
        char: charIndex,
        name: CHARACTERS[charIndex].name,
        portrait: portraits[charIndex],
        ring: CHARACTERS[charIndex].ring,
        x, y, mass,
        dirAngle: Math.random()*Math.PI*2,
        dirTimer: 0,
        aiMode: 'wander',
        chaseTarget: null,
        chaseTime: 0,
        playerCooldown: 0,
        role: 'normal',
      };
    }
  
    function makeCell(x, y, mass, vx, vy){
      return { x, y, mass, vx: vx||0, vy: vy||0, mergeAt: 0 };
    }
  
    function makePlayer(charIndex, x, y, mass){
      return {
        char: charIndex,
        name: CHARACTERS[charIndex].name,
        portrait: portraits[charIndex],
        ring: CHARACTERS[charIndex].ring,
        cells: [ makeCell(x, y, mass) ],
      };
    }
  
    function playerMass(){
      return player.cells.reduce((s,c) => s + c.mass, 0);
    }
    function playerCentroid(){
      let sx=0, sy=0, sm=0;
      player.cells.forEach(c => { sx += c.x*c.mass; sy += c.y*c.mass; sm += c.mass; });
      if (!sm) return { x: WORLD/2, y: WORLD/2 };
      return { x: sx/sm, y: sy/sm };
    }
  
    function radiusOf(mass){ return 16 + Math.sqrt(mass)*2.1; }
    function speedOf(mass){
  
      const m = Math.max(1, mass);
      return 320 / (1 + 0.028 * Math.pow(m, 0.80));
    }
  
    function aimDir(){
      if (window.nebulosaJoystick && window.nebulosaJoystick.active){
        const jx = window.nebulosaJoystick.x, jy = window.nebulosaJoystick.y;
        const len = Math.hypot(jx,jy) || 1;
        return { x: jx/len, y: jy/len };
      }
      const cx = window.innerWidth/2, cy = window.innerHeight/2;
      const dx = (pointerX ?? cx) - cx;
      const dy = (pointerY ?? cy) - cy;
      const len = Math.hypot(dx,dy) || 1;
      return { x: dx/len, y: dy/len };
    }
  
    function tryBoost(){
      ensureAudio();
      if (!running || playerMass() < BOOST_MIN_MASS || boostTimer > 0) return;
      const dir = aimDir();
      boostDirX = dir.x; boostDirY = dir.y;
      const total = playerMass() || 1;
      player.cells.forEach(c => { c.mass = Math.max(1, c.mass - BOOST_COST * (c.mass/total)); });
      boostTimer = BOOST_DURATION;
      sfxBoost();
    }
  
    function trySplit(){
      if (!running) return;
      const dir = aimDir();
      const now = performance.now()/1000;
      const snapshot = player.cells.slice();
      let splitAny = false;
      for (const cell of snapshot){
        if (player.cells.length >= MAX_CELLS) break;
        if (cell.mass >= MIN_SPLIT_MASS){
          const half = cell.mass/2;
          cell.mass = half;
          const nc = makeCell(cell.x, cell.y, half, dir.x*SPLIT_SPEED, dir.y*SPLIT_SPEED);
          const mergeAt = now + RECOMBINE_BASE + half/22;
          cell.mergeAt = mergeAt; nc.mergeAt = mergeAt;
          player.cells.push(nc);
          splitAny = true;
        }
      }
      if (splitAny){ ensureAudio(); sfxSplit(); }
    }
  
    function tryEject(){
      if (!running) return;
      const dir = aimDir();
      let ejectedAny = false;
      player.cells.forEach(cell => {
        if (cell.mass > EJECT_COST + 12){
          cell.mass -= EJECT_COST;
          const r = radiusOf(cell.mass);
          ejects.push({
            x: cell.x + dir.x*r, y: cell.y + dir.y*r,
            vx: dir.x*EJECT_SPEED, vy: dir.y*EJECT_SPEED,
            mass: EJECT_MASS, hue: Math.floor(Math.random()*360),
            bornAt: performance.now()
          });
          ejectedAny = true;
        }
      });
      if (ejectedAny){ ensureAudio(); sfxEject(); }
    }
  
    boostBtn.addEventListener('pointerdown', e => { e.stopPropagation(); tryBoost(); });
    ejectBtn.addEventListener('pointerdown', e => { e.stopPropagation(); tryEject(); });
    window.addEventListener('keydown', e => {
      if (e.code === 'Space'){ e.preventDefault(); trySplit(); }
      else if (e.code === 'KeyW'){ e.preventDefault(); tryEject(); }
      else if (e.code === 'ShiftLeft' || e.code === 'ShiftRight'){ e.preventDefault(); tryBoost(); }
    });
  
    function spawnFood(){
      food = [];
      for (let i=0;i<FOOD_COUNT;i++){
        food.push({
          x: randRange(40, WORLD-40),
          y: randRange(40, WORLD-40),
          hue: Math.floor(randRange(0,360)),
          r: randRange(3.5,5.5)
        });
      }
    }
  
    function respawnFoodAt(f){
      f.x = randRange(40, WORLD-40);
      f.y = randRange(40, WORLD-40);
      f.hue = Math.floor(randRange(0,360));
    }
  
    function spawnMovingOrbs(){
      movingOrbs = [];
      for (let i=0;i<MOVING_ORB_COUNT;i++){
        const a = Math.random()*Math.PI*2;
        movingOrbs.push({
          x: randRange(120,WORLD-120), y: randRange(120,WORLD-120),
          vx: Math.cos(a)*MOVING_ORB_SPEED, vy: Math.sin(a)*MOVING_ORB_SPEED,
          hue: Math.floor(randRange(0,360)), r: MOVING_ORB_RADIUS,
          turn: randRange(.8,2.2), phase: Math.random()*Math.PI*2
        });
      }
    }
  
    function updateMovingOrbs(dt){
      const elapsed = performance.now() - gameStartTime;
      let growth = 1;
      if (elapsed > MOVING_ORB_GROW_START){
        const t = Math.min(1, (elapsed-MOVING_ORB_GROW_START) /
          (MOVING_ORB_GROW_FULL-MOVING_ORB_GROW_START));
        growth = 1 + t * (MOVING_ORB_MAX_RADIUS/MOVING_ORB_RADIUS - 1);
      }
  
      const hunters = [
        ...(player?.cells || []),
        ...bots
      ];
      for (const o of movingOrbs){
        o.r = Math.min(MOVING_ORB_MAX_RADIUS, MOVING_ORB_RADIUS * growth);
        o.turn = Math.max(0, (o.turn||0)-dt);
        o.evadeTimer = Math.max(0, (o.evadeTimer||0)-dt);
        o.evadeCooldown = Math.max(0, (o.evadeCooldown||0)-dt);
  
        let danger=null, dangerDist=Infinity, dangerScore=0;
        for (const c of hunters){
          if (!c || c.mass < o.r*o.r*0.45) continue;
          const dx=c.x-o.x, dy=c.y-o.y, d=Math.hypot(dx,dy);
          if (d > MOVING_ORB_EVADE_RANGE) continue;
          const vx=c.vx||0, vy=c.vy||0;
          const closing=(dx*vx+dy*vy)/(d||1);
          const score=d - Math.max(0,closing)*0.8;
          if (score < dangerScore || danger===null){ danger=c; dangerDist=d; dangerScore=score; }
        }
  
        if (danger && o.evadeCooldown<=0){
          const dx=o.x-danger.x, dy=o.y-danger.y;
          const d=Math.hypot(dx,dy)||1;
          const awayX=dx/d, awayY=dy/d;
          const sideX=-awayY, sideY=awayX;
          const wobble=Math.sin(performance.now()/240 + o.phase)*0.55;
          let ex=awayX+sideX*wobble, ey=awayY+sideY*wobble;
          const el=Math.hypot(ex,ey)||1; ex/=el; ey/=el;
          const spd=Math.min(250, MOVING_ORB_SPEED*1.85 + Math.max(0,260-dangerDist)*0.35);
          o.vx=o.vx*0.25 + ex*spd*0.75;
          o.vy=o.vy*0.25 + ey*spd*0.75;
          o.evadeTimer=0.42;
          o.evadeCooldown=0.35;
        } else if (o.evadeTimer<=0 && o.turn<=0){
          const ang=Math.atan2(o.vy,o.vx)+randRange(-1.25,1.25);
          const spd=randRange(MOVING_ORB_SPEED*.85,MOVING_ORB_SPEED*1.15);
          o.vx=Math.cos(ang)*spd; o.vy=Math.sin(ang)*spd;
          o.turn=randRange(.55,1.8);
        }
  
        o.x += o.vx*dt; o.y += o.vy*dt;
        if (o.x<80 || o.x>WORLD-80){ o.vx*=-1; o.x=Math.max(80,Math.min(WORLD-80,o.x)); }
        if (o.y<80 || o.y>WORLD-80){ o.vy*=-1; o.y=Math.max(80,Math.min(WORLD-80,o.y)); }
      }
    }
  
    function spawnMassDrops(x,y,mass,count){
      const pieces=Math.max(1,Math.min(count,Math.ceil(mass/DROP_MASS)));
      const each=Math.max(2,mass/pieces);
      for(let i=0;i<pieces && massDrops.length<MAX_DROPS;i++){
        const ang=Math.random()*Math.PI*2, dist=randRange(8,42);
        massDrops.push({x:x+Math.cos(ang)*dist,y:y+Math.sin(ang)*dist,
          vx:Math.cos(ang)*randRange(110,260),vy:Math.sin(ang)*randRange(110,260),
          mass:each,hue:Math.floor(randRange(0,360)),bornAt:performance.now()});
      }
    }
  
    function updateMassDrops(dt){
      for(let i=massDrops.length-1;i>=0;i--){
        const d=massDrops[i]; d.x+=d.vx*dt; d.y+=d.vy*dt;
        const decay=Math.max(0,1-5.5*dt); d.vx*=decay; d.vy*=decay;
        d.x=Math.max(0,Math.min(WORLD,d.x)); d.y=Math.max(0,Math.min(WORLD,d.y));
        let eaten=false;
        for(const c of [...player.cells,...bots]){
          if(Math.hypot(c.x-d.x,c.y-d.y)<radiusOf(c.mass)*.72){c.mass+=d.mass; eaten=true; break;}
        }
        if(eaten || performance.now()-d.bornAt>18000) massDrops.splice(i,1);
      }
    }
  
    function eatMovingOrbs(){
      for(let i=movingOrbs.length-1;i>=0;i--){
        const o=movingOrbs[i];
        let eaten=false;
  
        for(const c of player.cells){
          const r=radiusOf(c.mass);
         
          if(Math.hypot(c.x-o.x,c.y-o.y) < r+o.r && r >= o.r*0.70){
            const reward = Math.max(MOVING_ORB_POINTS, Math.round(MOVING_ORB_POINTS*(o.r/MOVING_ORB_RADIUS)));
            c.mass += reward * (activePowers.double > 0 ? 2 : 1);
            eaten=true;
            break;
          }
        }
  
        if(!eaten) for(const b of bots){
          const r=radiusOf(b.mass);
          if(Math.hypot(b.x-o.x,b.y-o.y) < r+o.r && r >= o.r*0.70){
            const reward = Math.max(MOVING_ORB_POINTS, Math.round(MOVING_ORB_POINTS*(o.r/MOVING_ORB_RADIUS)));
            b.mass += reward;
            eaten=true;
            break;
          }
        }
  
        if(eaten) movingOrbs.splice(i,1);
      }
  
      while(movingOrbs.length<MOVING_ORB_COUNT){
        const a=Math.random()*Math.PI*2;
        movingOrbs.push({
          x:randRange(100,WORLD-100),
          y:randRange(100,WORLD-100),
          vx:Math.cos(a)*MOVING_ORB_SPEED,
          vy:Math.sin(a)*MOVING_ORB_SPEED,
          hue:Math.floor(randRange(0,360)),
          r:MOVING_ORB_RADIUS,
          turn:randRange(.8,2.2),
          phase:Math.random()*6.28,
          evadeTimer:0,
          evadeCooldown:randRange(0,2)
        });
      }
    }
  
    
    function spawnVirus(){
      viruses.push({ x: randRange(150, WORLD-150), y: randRange(150, WORLD-150), feed: 0 });
    }
    function spawnVirusNear(v){
      viruses.push({
        x: Math.max(60, Math.min(WORLD-60, v.x + randRange(-160,160))),
        y: Math.max(60, Math.min(WORLD-60, v.y + randRange(-160,160))),
        feed: 0
      });
    }
  
    function startGame(){
      stopMenuMusic();
      const mobileJoystick = document.getElementById('mobileJoystick');
      if (mobileJoystick) mobileJoystick.style.display = 'block';
      gameStartTime = performance.now();
      if (exitBtn) exitBtn.style.display = 'block';
      const online = mpToggle.checked && mpConnected;
      
      const isCustom = selectedSkin === 'custom' && !!customPortrait;
      const baseChar = isCustom ? 0 : (selectedSkin === 'custom' ? 0 : selectedSkin);
      player = makePlayer(baseChar, WORLD/2, WORLD/2, 5);
      if (isCustom){ player.portrait = customPortrait; player.ring = '#ffffff'; player.char = -1; }
      player.name = (document.getElementById('nickname')?.value || '').trim().slice(0,18) || (isCustom ? 'Jugador' : CHARACTERS[baseChar].name);
  
      bots = [];
      if (!online){
        for (let i=0;i<BOT_COUNT;i++){
          const ci = i % CHARACTERS.length;
          
          const roll = Math.random();
          const mass = roll < 0.62 ? randRange(8,28) : (roll < 0.90 ? randRange(28,55) : randRange(55,85));
          const bot = makeBlob(ci, randRange(200,WORLD-200), randRange(200,WORLD-200), mass);
          bot.name = BOT_NAMES[(i + Math.floor(Math.random()*BOT_NAMES.length)) % BOT_NAMES.length];
          bots.push(bot);
        }
       
        const boss = makeBlob((baseChar + 1) % CHARACTERS.length, randRange(600,WORLD-600), randRange(600,WORLD-600), 175);
        boss.name = 'Jefe Bot';
        boss.role = 'boss';
        boss.aiMode = 'hunt';
        bots.push(boss);
        for (let i=0;i<8;i++){
          const mid = makeBlob((i + 3) % CHARACTERS.length, randRange(300,WORLD-300), randRange(300,WORLD-300), randRange(95,135));
          mid.name = BOT_NAMES[(BOT_COUNT + i) % BOT_NAMES.length];
          mid.role = 'medium';
          bots.push(mid);
        }
      }
      remotePlayers.clear();
      ejects = [];
      massDrops = [];
      movingOrbs = [];
      viruses = [];
      for (let i=0;i<VIRUS_COUNT;i++) spawnVirus();
      spawnFood();
      spawnMovingOrbs();
      spawnPowerUps();
      resetPowers();
      if (!powerTipShown){ powerTipShown = true; setTimeout(() => { if (running && !powerCollected) showToast('Recoge los círculos con símbolos: ¡son poderes!', '#ffffff'); }, 1800); }
      running = true;
      startScreen.classList.add('hidden');
      gameOverScreen.classList.add('hidden');
      massPanel.style.display = 'block';
      leaderboardEl.style.display = 'block';
      minimapWrap.style.display = 'block';
      boostBtn.style.display = 'flex';
      ejectBtn.style.display = 'flex';
      boostTimer = 0;
      hint.style.display = 'block';
      hint.style.opacity = '1';
      setTimeout(()=>{ hint.style.opacity = '0'; }, 6500);
      if (online) {
        roomPanel.style.display = 'block';
        roomPanel.textContent = 'Sala: ' + mpRoom;
      } else {
        roomPanel.style.display = 'none';
      }
      pointerX = window.innerWidth/2; pointerY = window.innerHeight/2;
      lastTime = performance.now();
      requestAnimationFrame(loop);
    }
  
    function endGame(){
      const mobileJoystick = document.getElementById('mobileJoystick');
      if (mobileJoystick) mobileJoystick.style.display = 'none';
      running = false;
      resetPowers();
      sfxGameOver();
      finalMassEl.textContent = `Masa final: ${Math.floor(playerMass())}`;
      gameOverScreen.classList.remove('hidden');
      massPanel.style.display = 'none';
      leaderboardEl.style.display = 'none';
      minimapWrap.style.display = 'none';
      boostBtn.style.display = 'none';
      ejectBtn.style.display = 'none';
      roomPanel.style.display = 'none';
      hint.style.display = 'none';
    }
  
    function respawnBot(bot){
      bot.x = randRange(200, WORLD-200);
      bot.y = randRange(200, WORLD-200);
      const roll = Math.random();
      bot.mass = roll < 0.65 ? randRange(8,28) : (roll < 0.90 ? randRange(28,55) : randRange(55,85));
      if (bot.role !== 'boss' && bot.role !== 'medium') bot.name = BOT_NAMES[Math.floor(Math.random()*BOT_NAMES.length)];
    }
  

    /* ===== Power-ups ===== */
    const POWERUP_COUNT = 14;
    const POWERUP_R = 24;
    const POWER_SPEED_MULT = 1.55;
    const MAGNET_MULT = 2.6, MAGNET_ADD = 140;
    const POWER_DEFS = {
      speed:  { name:'Velocidad',  desc:'corres mucho más rápido', color:'#ffd23f', dur:8 },
      shield: { name:'Escudo',     desc:'nadie puede comerte',     color:'#4fc3ff', dur:6 },
      magnet: { name:'Imán',       desc:'atraes los orbes',        color:'#ff5d73', dur:10 },
      double: { name:'Doble masa', desc:'cada orbe da el doble',   color:'#7dff8b', dur:12 }
    };
    const POWER_KEYS = Object.keys(POWER_DEFS);
    const activePowers = { speed:0, shield:0, magnet:0, double:0 };
    let powerUps = [];
    let powerTipShown = false, powerCollected = false;
    const powerBadges = {};
    const powerHud = document.getElementById('powerHud');
    const toastEl = document.getElementById('toast');
    let toastTimer = null;

    function showToast(text, color){
      toastEl.textContent = text;
      toastEl.style.borderColor = color || '#fff';
      toastEl.classList.add('show');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => toastEl.classList.remove('show'), 2400);
    }
    function sfxPower(){
      if (!audioCtx) return;
      beep(500, 700, 0.08, 'triangle', 0.07);
      setTimeout(() => beep(700, 1000, 0.08, 'triangle', 0.07), 70);
      setTimeout(() => beep(1000, 1500, 0.14, 'triangle', 0.07), 140);
    }

    function spawnPowerUps(){
      powerUps = [];
      const types = [];
      for (let i = 0; i < POWERUP_COUNT; i++) types.push(POWER_KEYS[i % POWER_KEYS.length]);
      for (let i = types.length - 1; i > 0; i--){ const j = Math.floor(Math.random()*(i+1)); [types[i], types[j]] = [types[j], types[i]]; }
      types.forEach(t => powerUps.push({
        x: randRange(200, WORLD-200), y: randRange(200, WORLD-200),
        type: t, on: true, wait: 0, phase: Math.random()*6.28
      }));
    }
    function resetPowers(){
      POWER_KEYS.forEach(k => { activePowers[k] = 0; });
      Object.keys(powerBadges).forEach(k => { powerBadges[k].remove(); delete powerBadges[k]; });
      toastEl.classList.remove('show');
    }
    function collectPower(pu){
      const d = POWER_DEFS[pu.type];
      activePowers[pu.type] = d.dur;
      pu.on = false; pu.wait = randRange(8, 16);
      powerCollected = true;
      sfxPower();
      showToast(d.name + ' · ' + d.desc, d.color);
    }

    function drawPowerIcon(g, type, cx, cy, s, color){
      g.save(); g.translate(cx, cy);
      g.fillStyle = color; g.strokeStyle = color; g.lineJoin = 'round'; g.lineCap = 'round';
      if (type === 'speed'){
        const P = [[0.18,-1],[-0.6,0.12],[-0.08,0.12],[-0.22,1],[0.62,-0.22],[0.08,-0.22]];
        g.beginPath();
        P.forEach((q,i) => { if (i) g.lineTo(q[0]*s, q[1]*s); else g.moveTo(q[0]*s, q[1]*s); });
        g.closePath(); g.fill();
      } else if (type === 'shield'){
        g.beginPath();
        g.moveTo(0,-s); g.lineTo(0.82*s,-0.68*s); g.lineTo(0.82*s,0.08*s);
        g.quadraticCurveTo(0.82*s,0.68*s,0,s);
        g.quadraticCurveTo(-0.82*s,0.68*s,-0.82*s,0.08*s);
        g.lineTo(-0.82*s,-0.68*s); g.closePath(); g.fill();
        g.fillStyle = 'rgba(0,0,0,.35)';
        g.beginPath(); g.moveTo(0,-0.55*s); g.lineTo(0.42*s,-0.35*s); g.lineTo(0.42*s,0.1*s);
        g.quadraticCurveTo(0.42*s,0.4*s,0,0.62*s); g.closePath(); g.fill();
      } else if (type === 'magnet'){
        g.lineWidth = 0.42*s; g.lineCap = 'butt';
        g.beginPath();
        g.arc(0, 0.05*s, 0.6*s, Math.PI, 2*Math.PI);
        g.moveTo(-0.6*s, 0.05*s); g.lineTo(-0.6*s, 0.72*s);
        g.moveTo(0.6*s, 0.05*s);  g.lineTo(0.6*s, 0.72*s);
        g.stroke();
        g.fillStyle = '#fff';
        g.fillRect(-0.81*s, 0.46*s, 0.42*s, 0.26*s);
        g.fillRect(0.39*s, 0.46*s, 0.42*s, 0.26*s);
      } else {
        g.font = "800 " + (1.35*s).toFixed(1) + "px 'Work Sans', Arial, sans-serif";
        g.textAlign = 'center'; g.textBaseline = 'middle';
        g.fillText('x2', 0, 0.05*s);
      }
      g.restore();
    }
    const powerIconCache = {};
    function powerIconURL(type){
      if (powerIconCache[type]) return powerIconCache[type];
      const c = document.createElement('canvas'); c.width = c.height = 64;
      drawPowerIcon(c.getContext('2d'), type, 32, 32, 24, POWER_DEFS[type].color);
      return (powerIconCache[type] = c.toDataURL());
    }

    function updatePowerHud(){
      POWER_KEYS.forEach(k => {
        const left = activePowers[k], d = POWER_DEFS[k];
        let b = powerBadges[k];
        if (left > 0){
          if (!b){
            b = document.createElement('div');
            b.className = 'pbadge';
            b.style.setProperty('--c', d.color);
            b.innerHTML = '<img alt=""><i></i>';
            b.querySelector('img').src = powerIconURL(k);
            powerHud.appendChild(b);
            powerBadges[k] = b;
          }
          b.style.setProperty('--p', Math.min(100, left/d.dur*100).toFixed(1) + '%');
          b.querySelector('i').textContent = Math.ceil(left);
          b.classList.toggle('low', left < 2);
        } else if (b){
          b.remove(); delete powerBadges[k];
        }
      });
    }

    function updatePowers(dt){
      POWER_KEYS.forEach(k => { if (activePowers[k] > 0) activePowers[k] = Math.max(0, activePowers[k] - dt); });
      powerUps.forEach(pu => {
        if (!pu.on){
          pu.wait -= dt;
          if (pu.wait <= 0){
            pu.x = randRange(200, WORLD-200); pu.y = randRange(200, WORLD-200);
            pu.type = POWER_KEYS[Math.floor(Math.random()*POWER_KEYS.length)];
            pu.on = true;
          }
          return;
        }
        for (const c of player.cells){
          if (Math.hypot(c.x-pu.x, c.y-pu.y) < radiusOf(c.mass)*0.9 + POWERUP_R){ collectPower(pu); break; }
        }
      });
      if (activePowers.magnet > 0){
        for (const c of player.cells){
          const range = radiusOf(c.mass)*MAGNET_MULT + MAGNET_ADD, r2 = range*range;
          for (const f of food){
            const dx = c.x - f.x, dy = c.y - f.y, d2 = dx*dx + dy*dy;
            if (d2 < r2 && d2 > 1){
              const d = Math.sqrt(d2);
              const pull = Math.min(d, (420 + (1 - d/range)*900) * dt);
              f.x += dx/d*pull; f.y += dy/d*pull;
            }
          }
        }
      }
      updatePowerHud();
    }

    function drawPowerUps(toScreen, zoom){
      const now = performance.now()/1000;
      powerUps.forEach(pu => {
        if (!pu.on) return;
        const [sx, sy] = toScreen(pu.x, pu.y);
        const R = Math.max(POWERUP_R*zoom, 14);
        if (sx < -R*3 || sx > canvas.width + R*3 || sy < -R*3 || sy > canvas.height + R*3) return;
        const d = POWER_DEFS[pu.type];
        const r = R * 1.25 * (1 + Math.sin(now*3 + pu.phase)*0.08);
        ctx.save();
        ctx.shadowBlur = 22; ctx.shadowColor = d.color;
        ctx.beginPath(); ctx.arc(sx, sy, r, 0, Math.PI*2);
        ctx.fillStyle = 'rgba(0,0,0,.8)'; ctx.fill();
        ctx.lineWidth = 3; ctx.strokeStyle = d.color; ctx.stroke();
        ctx.restore();
        const a = now*2 + pu.phase;
        ctx.save();
        ctx.beginPath(); ctx.arc(sx, sy, r + 6, a, a + Math.PI*0.9);
        ctx.globalAlpha = 0.6; ctx.lineWidth = 2.5; ctx.strokeStyle = d.color; ctx.stroke();
        ctx.restore();
        drawPowerIcon(ctx, pu.type, sx, sy, r*0.62, d.color);
      });
    }

    function drawAuras(sx, sy, r, zoom, mass){
      const t = performance.now()/1000;
      if (activePowers.magnet > 0){
        const range = (radiusOf(mass)*MAGNET_MULT + MAGNET_ADD) * zoom;
        ctx.save();
        ctx.setLineDash([9, 12]); ctx.lineDashOffset = -t*40;
        ctx.lineWidth = 2; ctx.strokeStyle = 'rgba(255,93,115,.55)';
        ctx.beginPath(); ctx.arc(sx, sy, range, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
      }
      if (activePowers.double > 0){
        ctx.save();
        ctx.lineWidth = Math.max(2, r*0.05); ctx.strokeStyle = 'rgba(125,255,139,.75)';
        ctx.beginPath(); ctx.arc(sx, sy, r*1.14, 0, Math.PI*2); ctx.stroke();
        ctx.fillStyle = '#7dff8b';
        for (let i = 0; i < 3; i++){
          const ang = t*2.2 + i*2.094;
          ctx.beginPath();
          ctx.arc(sx + Math.cos(ang)*r*1.3, sy + Math.sin(ang)*r*1.3, Math.max(3, r*0.07), 0, Math.PI*2);
          ctx.fill();
        }
        ctx.restore();
      }
      if (activePowers.speed > 0){
        const dir = aimDir();
        ctx.save();
        ctx.shadowBlur = 18; ctx.shadowColor = '#ffd23f';
        ctx.lineWidth = Math.max(2.5, r*0.06); ctx.strokeStyle = 'rgba(255,210,63,.85)';
        ctx.beginPath(); ctx.arc(sx, sy, r*1.08, 0, Math.PI*2); ctx.stroke();
        ctx.shadowBlur = 0; ctx.lineCap = 'round';
        for (let k = -1; k <= 1; k++){
          const bx = sx - dir.x*r*1.2 + (-dir.y)*k*r*0.5;
          const by = sy - dir.y*r*1.2 + dir.x*k*r*0.5;
          const len = r*(0.7 + 0.25*Math.sin(t*20 + k));
          ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx - dir.x*len, by - dir.y*len);
          ctx.globalAlpha = 0.55; ctx.lineWidth = Math.max(2, r*0.05); ctx.strokeStyle = '#ffd23f'; ctx.stroke();
        }
        ctx.restore();
      }
      if (activePowers.shield > 0){
        const low = activePowers.shield < 2 && Math.sin(t*16) < 0;
        const al = low ? 0.3 : 1;
        ctx.save();
        ctx.globalAlpha = al;
        ctx.beginPath(); ctx.arc(sx, sy, r*1.2, 0, Math.PI*2);
        ctx.fillStyle = 'rgba(79,195,255,.16)'; ctx.fill();
        ctx.lineWidth = Math.max(3, r*0.07); ctx.strokeStyle = 'rgba(130,215,255,.95)';
        ctx.shadowBlur = 16; ctx.shadowColor = '#4fc3ff'; ctx.stroke();
        ctx.restore();
      }
    }

    let lastTime = performance.now();
    function loop(now){
      if (!running) return;
      const dt = Math.min((now-lastTime)/1000, 0.05);
      lastTime = now;
      update(dt);
      draw();
      requestAnimationFrame(loop);
    }
  
  
    function moveBlobToward(blob, dx, dy, dt, speedMult){
      const len = Math.hypot(dx,dy) || 1;
      const spd = speedOf(blob.mass) * (speedMult || 1);
      blob.x += dx/len*spd*dt;
      blob.y += dy/len*spd*dt;
      blob.x = Math.max(0, Math.min(WORLD, blob.x));
      blob.y = Math.max(0, Math.min(WORLD, blob.y));
    }
  
    function moveCellToward(cell, dx, dy, dt, speedMult){
      const len = Math.hypot(dx,dy) || 1;
      const spd = speedOf(cell.mass) * (speedMult || 1);
      cell.x += dx/len*spd*dt;
      cell.y += dy/len*spd*dt;
    }
  
    function applyImpulse(cell, dt){
      if (Math.abs(cell.vx) > 0.5 || Math.abs(cell.vy) > 0.5){
        cell.x += cell.vx*dt;
        cell.y += cell.vy*dt;
        const decay = Math.max(0, 1 - IMPULSE_DRAG*dt);
        cell.vx *= decay; cell.vy *= decay;
      } else { cell.vx = 0; cell.vy = 0; }
    }
  
    function clampCell(cell){
      cell.x = Math.max(0, Math.min(WORLD, cell.x));
      cell.y = Math.max(0, Math.min(WORLD, cell.y));
    }
  
    function separatePlayerCells(){
      const cells = player.cells;
      for (let i=0;i<cells.length;i++){
        for (let j=i+1;j<cells.length;j++){
          const a = cells[i], b = cells[j];
          const dx = b.x-a.x, dy = b.y-a.y;
          const dist = Math.hypot(dx,dy) || 0.001;
          const minDist = (radiusOf(a.mass)+radiusOf(b.mass)) * 0.6;
          if (dist < minDist){
            const overlap = (minDist-dist)/2;
            const ux = dx/dist, uy = dy/dist;
            a.x -= ux*overlap; a.y -= uy*overlap;
            b.x += ux*overlap; b.y += uy*overlap;
          }
        }
      }
    }
  
    function tryRecombinePlayer(){
      const now = performance.now()/1000;
      const cells = player.cells;
      for (let i=0;i<cells.length;i++){
        for (let j=i+1;j<cells.length;j++){
          const a = cells[i], b = cells[j];
          if (now < a.mergeAt || now < b.mergeAt) continue;
          const dist = Math.hypot(a.x-b.x, a.y-b.y);
          if (dist < (radiusOf(a.mass)+radiusOf(b.mass))*0.5){
            a.mass += b.mass;
            cells.splice(j,1);
            return; 
          }
        }
      }
    }
  
   
    function collectAllPoints(){
      const pts = [];
      player.cells.forEach(c => pts.push({ x:c.x, y:c.y, mass:c.mass, ref:player }));
      bots.forEach(b => pts.push({ x:b.x, y:b.y, mass:b.mass, ref:b }));
      if (mpConnected) remotePlayers.forEach(rp => { if (rp.mass > 0) pts.push({ x:rp.x, y:rp.y, mass:rp.mass, ref:rp }); });
      return pts;
    }
  
    function updateBotAI(bot, dt, points){
      bot.playerCooldown = Math.max(0, (bot.playerCooldown||0) - dt);

      // 1) Mirar alrededor: amenazas (más grandes) empujan, presas (más chicas) atraen
      let fx = 0, fy = 0, nearThreat = Infinity;
      let prey = null, preyScore = 0;
      for (const p of points){
        if (p.ref === bot) continue;
        const dx = p.x - bot.x, dy = p.y - bot.y;
        const d = Math.hypot(dx, dy) || 1;
        if (d > BOT_VIEW) continue;
        if (p.mass > bot.mass*1.15){
          const w = 1 - d/BOT_VIEW;
          fx -= dx/d * w*w; fy -= dy/d * w*w;
          if (d < nearThreat) nearThreat = d;
        } else if (bot.mass > p.mass*1.15){
          if (p.ref === player && bot.playerCooldown > 0) continue;
          const score = p.mass / (d + 80);   // prefiere presas jugosas y cercanas
          if (score > preyScore){ prey = p; preyScore = score; }
        }
      }

      // 2) Decidir: huir > perseguir > buscar comida > vagar
      let dirX, dirY, fleeing = false;
      if (nearThreat < BOT_VIEW*0.85){
        fleeing = true;
        bot.aiMode = 'flee'; bot.chaseTarget = null; bot.chaseTime = 0;
        dirX = fx; dirY = fy;
      } else if (prey){
        const isPlayer = prey.ref === player;
        if (isPlayer){
          if (bot.chaseTarget !== player){ bot.chaseTarget = player; bot.chaseTime = 0; }
          bot.chaseTime += dt;
        } else {
          bot.chaseTarget = prey.ref; bot.chaseTime = 0;
        }
        if (isPlayer && bot.chaseTime >= 30){
          bot.playerCooldown = 10; bot.chaseTarget = null; bot.chaseTime = 0;
          bot.aiMode = 'wander'; bot.dirAngle += randRange(1.8, 3.8);
          dirX = Math.cos(bot.dirAngle); dirY = Math.sin(bot.dirAngle);
        } else {
          bot.aiMode = (isPlayer && bot.role === 'boss') ? 'boss-hunt' : 'chase';
          dirX = prey.x - bot.x; dirY = prey.y - bot.y;
        }
      } else {
        bot.chaseTarget = null; bot.chaseTime = 0;
        // buscar el orbe más cercano
        bot.foodTimer = (bot.foodTimer || 0) - dt;
        let t = bot.foodTarget;
        if (!t || bot.foodTimer <= 0 || Math.hypot(t.x-bot.x, t.y-bot.y) > 1300){
          bot.foodTimer = randRange(0.5, 1);
          let best = null, bd = 1100*1100;
          for (const f of food){
            const ddx = f.x - bot.x, ddy = f.y - bot.y;
            const d2 = ddx*ddx + ddy*ddy;
            if (d2 < bd){ bd = d2; best = f; }
          }
          bot.foodTarget = t = best;
        }
        if (t){
          bot.aiMode = 'food';
          dirX = t.x - bot.x; dirY = t.y - bot.y;
        } else {
          bot.aiMode = 'wander';
          bot.dirTimer -= dt;
          if (bot.dirTimer <= 0){ bot.dirAngle += randRange(-1.4, 1.4); bot.dirTimer = randRange(1, 2.4); }
          dirX = Math.cos(bot.dirAngle); dirY = Math.sin(bot.dirAngle);
        }
      }

      // 3) Evitar los bordes del mapa (para no quedar acorralados)
      const len = Math.hypot(dirX, dirY) || 1;
      dirX /= len; dirY /= len;
      const M = 420, k = fleeing ? 1.6 : 0.7;
      if (bot.x < M) dirX += (M - bot.x)/M * k; else if (bot.x > WORLD-M) dirX -= (bot.x - (WORLD-M))/M * k;
      if (bot.y < M) dirY += (M - bot.y)/M * k; else if (bot.y > WORLD-M) dirY -= (bot.y - (WORLD-M))/M * k;

      // 4) Evitar virus si ya son lo bastante grandes como para reventar
      if (bot.mass > VIRUS_POP_MASS*0.75){
        const br = radiusOf(bot.mass);
        for (const v of viruses){
          const vx = bot.x - v.x, vy = bot.y - v.y;
          const vd = Math.hypot(vx, vy) || 1;
          if (vd < br + VIRUS_RADIUS + 90){ dirX += vx/vd * 1.4; dirY += vy/vd * 1.4; }
        }
      }

      moveBlobToward(bot, dirX, dirY, dt, bot.role === 'boss' ? 0.94 : 1);
    }

   
    function eatFood(){
      let ate = false;
      const eaters = [...player.cells, ...bots];
      eaters.forEach(cell => {
        const r = radiusOf(cell.mass);
        const isP = player.cells.indexOf(cell) !== -1;
        const gain = (isP && activePowers.double > 0) ? 8 : 4;
        food.forEach(f => {
          const d = Math.hypot(f.x-cell.x, f.y-cell.y);
          if (d < r){ cell.mass += gain; respawnFoodAt(f); if (isP) ate = true; }
        });
      });
      if (ate) sfxEat();
    }
  
  
    function updateEjects(dt){
      for (let i=ejects.length-1;i>=0;i--){
        const e = ejects[i];
        e.x += e.vx*dt; e.y += e.vy*dt;
        const decay = Math.max(0, 1-6*dt);
        e.vx *= decay; e.vy *= decay;
        e.x = Math.max(0, Math.min(WORLD, e.x));
        e.y = Math.max(0, Math.min(WORLD, e.y));
  
        let consumed = false;
        for (const v of viruses){
          const d = Math.hypot(v.x-e.x, v.y-e.y);
          if (d < VIRUS_RADIUS){
            v.feed = (v.feed||0) + 1;
            if (v.feed >= VIRUS_FEED_LIMIT){
              v.feed = 0;
              spawnVirusNear(v);
            }
            ejects.splice(i,1); consumed = true; break;
          }
        }
        if (consumed) continue;
  
        const age = performance.now() - e.bornAt;
        if (age > 220){
          const eaters = [...player.cells, ...bots];
          for (const cell of eaters){
            const d = Math.hypot(cell.x-e.x, cell.y-e.y);
            if (d < radiusOf(cell.mass)){
              cell.mass += e.mass;
              ejects.splice(i,1); consumed = true; break;
            }
          }
        }
        if (consumed) continue;
  
        if (performance.now() - e.bornAt > 20000) ejects.splice(i,1);
      }
    }
  
   
    function popCell(cell, index){
      const piecesWanted = 8;
      const room = Math.max(2, MAX_CELLS - (player.cells.length - 1));
      const pieces = Math.max(2, Math.min(piecesWanted, room));
      const totalMassBefore = cell.mass;
      const each = totalMassBefore/pieces;
      player.cells.splice(index,1);
      const now = performance.now()/1000;
      for (let k=0;k<pieces;k++){
        const ang = (Math.PI*2/pieces)*k + Math.random()*0.3;
        const launch = SPLIT_SPEED * randRange(0.88, 1.12);
        const spread = randRange(0.86, 1.10);
        const nc = makeCell(cell.x + Math.cos(ang)*randRange(2,8), cell.y + Math.sin(ang)*randRange(2,8), each, Math.cos(ang)*launch*spread, Math.sin(ang)*launch*spread);
        nc.mergeAt = now + RECOMBINE_BASE + each/22;
        player.cells.push(nc);
      }
      sfxVirus();
    }
  
    function updateVirusCollisions(){
      if (activePowers.shield > 0) return;
      for (let i=player.cells.length-1;i>=0;i--){
        const cell = player.cells[i];
        if (cell.mass < VIRUS_POP_MASS) continue;
        for (let vi=0; vi<viruses.length; vi++){
          const v = viruses[vi];
          const d = Math.hypot(cell.x-v.x, cell.y-v.y);
        
          const cellRadius = radiusOf(cell.mass);
          const isLargeEnough = cellRadius >= VIRUS_RADIUS * 0.92;
          if (isLargeEnough && d < cellRadius * 0.82 + VIRUS_RADIUS * 0.62){
            popCell(cell, i);
            viruses.splice(vi,1);
            spawnVirus();
            break;
          }
        }
      }
    }
  
    
    function damageAndEat(winner, victim, winnerIsPlayer){
      if (activePowers.shield > 0 && player.cells.indexOf(victim) !== -1) return false;
      if (winner.mass <= victim.mass*1.15) return false;
      const lost = Math.min(victim.mass, Math.max(DAMAGE_MIN_MASS, victim.mass*DAMAGE_RATIO));
      const gained = lost*0.82;
      victim.mass -= lost;
      winner.mass += gained;
      spawnMassDrops(victim.x,victim.y,lost-gained*0.15,Math.max(2,Math.ceil(lost/DROP_MASS)));
      if (winnerIsPlayer) sfxAbsorb();
      return victim.mass < 3;
    }
  
    function handleEating(){
      const list=[];
      player.cells.forEach(c=>list.push({type:'player',cell:c}));
      bots.forEach(b=>list.push({type:'bot',cell:b}));
      for(let i=0;i<list.length;i++) for(let j=i+1;j<list.length;j++){
        const A=list[i],B=list[j]; if(A.type==='player'&&B.type==='player') continue;
        const a=A.cell,b=B.cell; if(a.mass<=0||b.mass<=0) continue;
        const d=Math.hypot(a.x-b.x,a.y-b.y);
        if(d<Math.max(radiusOf(a.mass),radiusOf(b.mass))*.72){
          if(damageAndEat(a,b,A.type==='player')) b.mass=0;
          else if(damageAndEat(b,a,B.type==='player')) a.mass=0;
        }
      }
      player.cells=player.cells.filter(c=>c.mass>0);
      bots.forEach(b=>{if(b.mass<=0) respawnBot(b);});
      if(player.cells.length===0) endGame();
    }
  
    function handleRemoteInteractions(){
      if (!mpConnected || !running) return;
      remotePlayers.forEach((rp, id) => {
        if (!rp.mass || rp.mass <= 0) return;
        for (const cell of player.cells){
          if (cell.mass <= 0) continue;
          const d = Math.hypot(cell.x-rp.x, cell.y-rp.y);
          const ra = radiusOf(cell.mass), rb = radiusOf(rp.mass);
          if (d < Math.max(ra,rb)*0.72){
            if (cell.mass > rp.mass*1.15){
              const lost=Math.min(rp.mass,Math.max(DAMAGE_MIN_MASS,rp.mass*DAMAGE_RATIO));
              cell.mass += lost*0.82;
              spawnMassDrops(rp.x,rp.y,lost*.85,Math.max(2,Math.ceil(lost/DROP_MASS)));
              rp.mass -= lost;
              if(rp.mass<3){ remotePlayers.delete(id); mpSendEat(id); }
              sfxAbsorb();
            } else if (rp.mass > cell.mass*1.15 && activePowers.shield <= 0){
              const lost=Math.min(cell.mass,Math.max(DAMAGE_MIN_MASS,cell.mass*DAMAGE_RATIO));
              cell.mass-=lost;
              spawnMassDrops(cell.x,cell.y,lost*.85,Math.max(2,Math.ceil(lost/DROP_MASS)));
            }
          }
        }
      });
      player.cells = player.cells.filter(c => c.mass > 0);
      if (player.cells.length === 0) endGame();
    }
  
    function update(dt){
      if (!running) return;
  
      
      if (boostTimer > 0){
        boostTimer -= dt;
        player.cells.forEach(c => moveCellToward(c, boostDirX, boostDirY, dt, BOOST_SPEED_MULT * (activePowers.speed > 0 ? POWER_SPEED_MULT : 1)));
      } else {
        const cx = window.innerWidth/2, cy = window.innerHeight/2;
        let dx, dy, shouldMove;
        if (window.nebulosaJoystick && window.nebulosaJoystick.active) {
          
          dx = window.nebulosaJoystick.x;
          dy = window.nebulosaJoystick.y;
          shouldMove = Math.hypot(dx,dy) > 0.08;
        } else {
          dx = (pointerX ?? cx) - cx;
          dy = (pointerY ?? cy) - cy;
          shouldMove = Math.hypot(dx,dy) > 8;
        }
        if (shouldMove) player.cells.forEach(c => moveCellToward(c, dx, dy, dt, activePowers.speed > 0 ? POWER_SPEED_MULT : 1));
      }
      player.cells.forEach(c => { applyImpulse(c, dt); clampCell(c); });
      separatePlayerCells();
      tryRecombinePlayer();
      if (!running || player.cells.length === 0) return;
  
      
      const points = collectAllPoints();
      bots.forEach(b => updateBotAI(b, dt, points));
  
      
      updatePowers(dt);
      eatFood();
      updateMovingOrbs(dt);
      eatMovingOrbs();
      updateMassDrops(dt);
      updateEjects(dt);
      updateVirusCollisions();
      if (!running || player.cells.length === 0) return;
  
     
      handleEating();
      if (!running) return;
      handleRemoteInteractions();
      if (!running) return;
  
      if (mpConnected){ mpSendState(); mpPruneStale(); }
    }
  
    const bgStars = new Image();
    (function(){
      const v = getComputedStyle(document.documentElement).getPropertyValue('--stars');
      const mm = /url\(\s*['"]?([^'")]+)['"]?\s*\)/.exec(v);
      if (mm) bgStars.src = mm[1];
    })();

    function draw(){
      ctx.fillStyle = '#000';
      ctx.fillRect(0,0,canvas.width,canvas.height);
  
      const totalMass = playerMass();
      const zoom = Math.max(0.4, Math.min(1.05, 1.15 - totalMass/1600));
      const cen = playerCentroid();
      const camX = cen.x, camY = cen.y;
      const w2 = canvas.width/2, h2 = canvas.height/2;
      function toScreen(x,y){ return [ (x-camX)*zoom + w2, (y-camY)*zoom + h2 ]; }
  
      if (bgStars.naturalWidth){
        const tw = 1400, th = tw * bgStars.naturalHeight / bgStars.naturalWidth;
        const ox = ((-camX*0.15) % tw + tw) % tw, oy = ((-camY*0.15) % th + th) % th;
        for (let x = ox - tw; x < canvas.width; x += tw)
          for (let y = oy - th; y < canvas.height; y += th) ctx.drawImage(bgStars, x, y, tw, th);
      }

      ctx.strokeStyle = 'rgba(255,255,255,0.05)';
      ctx.lineWidth = 1;
      const gridSize = 120*zoom;
      const offX = ((-camX*zoom) % gridSize + gridSize) % gridSize;
      const offY = ((-camY*zoom) % gridSize + gridSize) % gridSize;
      for (let x=offX; x<canvas.width; x+=gridSize){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,canvas.height); ctx.stroke(); }
      for (let y=offY; y<canvas.height; y+=gridSize){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(canvas.width,y); ctx.stroke(); }
  
      const [bx1,by1] = toScreen(0,0);
      const [bx2,by2] = toScreen(WORLD,WORLD);
      ctx.strokeStyle = 'rgba(201,169,97,0.4)';
      ctx.lineWidth = 3;
      ctx.strokeRect(bx1,by1,bx2-bx1,by2-by1);
  
      food.forEach(f => {
        const [sx,sy] = toScreen(f.x,f.y);
        if (sx<-20||sx>canvas.width+20||sy<-20||sy>canvas.height+20) return;
        ctx.beginPath();
        ctx.fillStyle = `hsl(${f.hue}, 70%, 65%)`;
        ctx.arc(sx, sy, f.r*zoom, 0, Math.PI*2);
        ctx.fill();
      });
  
      movingOrbs.forEach(o => {
        const [sx,sy]=toScreen(o.x,o.y); const pulse=1+Math.sin(performance.now()/180+o.phase)*.10;
        const r=o.r*zoom*pulse; if(sx<-30||sx>canvas.width+30||sy<-30||sy>canvas.height+30)return;
        ctx.save(); ctx.shadowBlur=12; ctx.shadowColor=`hsl(${o.hue},90%,65%)`;
        ctx.beginPath(); ctx.fillStyle=`hsl(${o.hue},85%,68%)`; ctx.arc(sx,sy,r,0,Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.strokeStyle='rgba(255,255,255,.55)'; ctx.lineWidth=1.5; ctx.arc(sx,sy,r,0,Math.PI*2); ctx.stroke(); ctx.restore();
      });
  
      drawPowerUps(toScreen, zoom);

      massDrops.forEach(d => {
        const [sx,sy]=toScreen(d.x,d.y); const r=Math.max(4,Math.min(10,radiusOf(d.mass)*.42))*zoom;
        if(sx<-20||sx>canvas.width+20||sy<-20||sy>canvas.height+20)return;
        ctx.beginPath(); ctx.fillStyle=`hsl(${d.hue},75%,62%)`; ctx.arc(sx,sy,r,0,Math.PI*2); ctx.fill();
      });
  
      ejects.forEach(e => {
        const [sx,sy] = toScreen(e.x,e.y);
        if (sx<-20||sx>canvas.width+20||sy<-20||sy>canvas.height+20) return;
        ctx.beginPath();
        ctx.fillStyle = `hsl(${e.hue}, 75%, 60%)`;
        ctx.arc(sx, sy, 8*zoom, 0, Math.PI*2);
        ctx.fill();
      });
  
      viruses.forEach(v => {
        const [sx,sy] = toScreen(v.x,v.y);
        const r = VIRUS_RADIUS*zoom;
        if (sx<-r-10||sx>canvas.width+r+10||sy<-r-10||sy>canvas.height+r+10) return;
        ctx.save();
        ctx.translate(sx,sy);
        ctx.beginPath();
        const spikes = 18;
        for (let i=0;i<spikes;i++){
          const ang = (Math.PI*2/spikes)*i;
          const rr = r * (i%2===0 ? 1 : 0.82);
          const px = Math.cos(ang)*rr, py = Math.sin(ang)*rr;
          if (i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
        }
        ctx.closePath();
        ctx.fillStyle = 'rgba(121,196,143,0.92)';
        ctx.strokeStyle = 'rgba(42,104,62,0.95)';
        ctx.lineWidth = 3;
        ctx.fill(); ctx.stroke();
        
        ctx.beginPath();
        ctx.arc(0, 0, r*0.70, 0, Math.PI*2);
        ctx.fillStyle = 'rgba(165,230,175,0.13)';
        ctx.fill();
        ctx.restore();
      });
  
      const remoteList = mpConnected ? Array.from(remotePlayers.values()).filter(r => r.mass > 0) : [];
      const drawList = [];
      player.cells.forEach(c => drawList.push({ x:c.x, y:c.y, mass:c.mass, portrait: player.portrait, ring:'#e8c777', name: player.name, isPlayer:true }));
      bots.forEach(b => drawList.push({ x:b.x, y:b.y, mass:b.mass, portrait:b.portrait, ring:b.ring, name:b.name }));
      remoteList.forEach(r => drawList.push({ x:r.x, y:r.y, mass:r.mass, portrait:r.portrait, ring:r.ring, name:r.name }));
      drawList.sort((a,b)=>a.mass-b.mass);
      drawList.forEach(blob => {
        const [sx,sy] = toScreen(blob.x, blob.y);
        const r = radiusOf(blob.mass)*zoom;
        if (sx<-r-40||sx>canvas.width+r+40||sy<-r-40||sy>canvas.height+r+40) return;
        ctx.save();
        ctx.beginPath(); ctx.arc(sx,sy,r,0,Math.PI*2); ctx.closePath(); ctx.clip();
        ctx.drawImage(blob.portrait, sx-r, sy-r, r*2, r*2);
        ctx.restore();
        ctx.beginPath();
        ctx.arc(sx,sy,r,0,Math.PI*2);
        ctx.lineWidth = Math.max(2, r*0.08);
        ctx.strokeStyle = blob.isPlayer ? '#e8c777' : blob.ring;
        ctx.stroke();
        if (blob.isPlayer) drawAuras(sx, sy, r, zoom, blob.mass);
        if (blob.mass > 20){
          ctx.font = `600 ${Math.max(11, r*0.24)}px 'Work Sans', sans-serif`;
          ctx.fillStyle = 'rgba(232,220,196,0.95)';
          ctx.textAlign = 'center';
          ctx.fillText(blob.name, sx, sy + r + 14);
        }
      });
  
      massPanel.textContent = `Masa: ${Math.floor(totalMass)}`;
  
      const boardEntries = [
        { name: player.name + ' (tú)', mass: totalMass, isPlayer:true },
        ...bots.map(b => ({ name:b.name, mass:b.mass })),
        ...remoteList.map(r => ({ name:r.name, mass:r.mass }))
      ];
      const ranked = boardEntries.sort((a,b)=>b.mass-a.mass).slice(0,10);
      leaderboardList.innerHTML = ranked.map(b => `<li class="${b.isPlayer?'me':''}">${b.name} — ${Math.floor(b.mass)}</li>`).join('');
  
      drawMinimap(drawList);
    }
  
    function drawMinimap(all){
      mctx.clearRect(0,0,130,130);
      mctx.fillStyle = 'rgba(0,0,0,0.85)';
      mctx.fillRect(0,0,130,130);
      mctx.strokeStyle = 'rgba(255,255,255,0.7)';
      mctx.strokeRect(1,1,128,128);
      viruses.forEach(v => {
        const mx = (v.x/WORLD)*130, my = (v.y/WORLD)*130;
        mctx.beginPath(); mctx.fillStyle = 'rgba(121,196,143,0.75)';
        mctx.arc(mx, my, 2, 0, Math.PI*2); mctx.fill();
      });
      powerUps.forEach(pu => {
        if (!pu.on) return;
        mctx.fillStyle = POWER_DEFS[pu.type].color;
        mctx.fillRect((pu.x/WORLD)*130 - 1.5, (pu.y/WORLD)*130 - 1.5, 3, 3);
      });
      all.forEach(b => {
        const mx = (b.x/WORLD)*130, my = (b.y/WORLD)*130;
        mctx.beginPath();
        mctx.fillStyle = b.isPlayer ? '#79c48f' : b.ring;
        mctx.arc(mx, my, b.isPlayer ? 4 : 2.6, 0, Math.PI*2);
        mctx.fill();
      });
    }
  
    Promise.all(CHARACTERS.map(c => loadImage(c.img))).then(imgs => {
      portraits = imgs.map((img,i) => circularCanvas(img, 200, PORTRAIT_CROPS[i]));
      CHARACTERS.forEach((c,i) => {
        const opt = document.createElement('div');
        opt.className = 'skin-option';
        opt.innerHTML = `<img src="${portraits[i].toDataURL()}"><span>${c.name}</span>`;
        opt.addEventListener('click', () => {
          document.querySelectorAll('.skin-option').forEach(o => o.classList.remove('selected'));
          opt.classList.add('selected');
          selectedSkin = i;
          playBtn.disabled = false;
        });
        skinRow.appendChild(opt);
      });
      buildCustomOption();
    });
  
    playBtn.addEventListener('click', () => {
      if (selectedSkin === null) {
        const fm = document.getElementById('formMsg'); fm.textContent = 'Elige un personaje con el botón +'; fm.className = 'mp-status err';
        skinPicker.classList.remove('hidden');
        return;
      }
      ensureAudio();
      if (!mpToggle.checked) { sfxStart(); startGame(); return; }
      const code = mpRoomCode.value.trim().toUpperCase();
      if (mpConnected && mpRoom && (!code || code === mpRoom)) { sfxStart(); startGame(); return; }
      if (!code) { mpSetStatus('Genera un código o escribe uno.', 'err'); return; }
      pendingStart = true;
      mpOpenSocket({ type: 'join', code });
    });
    retryBtn.addEventListener('click', () => {
      if (selectedSkin !== null) { ensureAudio(); sfxStart(); startGame(); }
    });
    changeSkinBtn.addEventListener('click', () => { showWelcome(); });

    /* ===== Navegación entre pantallas ===== */
    const welcomeScreen = document.getElementById('welcomeScreen');
    const goSoloBtn = document.getElementById('goSoloBtn');
    const goOnlineBtn = document.getElementById('goOnlineBtn');
    const backBtn = document.getElementById('backBtn');
    const pickBtn = document.getElementById('pickBtn');
    const pickImg = document.getElementById('pickImg');
    const skinPicker = document.getElementById('skinPicker');

    function showWelcome(){
      playMenuMusic();
      mpReset();
      gameOverScreen.classList.add('hidden');
      startScreen.classList.add('hidden');
      skinPicker.classList.add('hidden');
      welcomeScreen.classList.remove('hidden');
    }
    function showForm(online){
      playMenuMusic();
      mpReset();
      mpToggle.checked = online;
      startScreen.classList.toggle('online', online);
      skinPicker.classList.add('hidden');
      welcomeScreen.classList.add('hidden');
      startScreen.classList.remove('hidden');
      if (online) mpWake();
    }


    /* ===== Foto propia ===== */
    const PHOTO_KEY = 'nebulosa_foto_v1';
    let customPortrait = null;   // retrato circular de 200 px
    let customSmallURL = null;   // jpeg de 128 px que se manda a los demás en online
    let customOpt = null;
    const photoInput = document.getElementById('photoInput');
    const photoEditor = document.getElementById('photoEditor');
    const peCanvas = document.getElementById('peCanvas');
    const peCtx = peCanvas.getContext('2d');
    const peZoom = document.getElementById('peZoom');
    const PE_S = 300, PE_D = 260;
    const pe = { img:null, sw:1, sh:1, base:1, zoom:1, ox:0, oy:0 };

    function portraitFor(sel){ return sel === 'custom' ? customPortrait : portraits[sel]; }

    let blankPortrait = null;
    function getBlankPortrait(){
      if (blankPortrait) return blankPortrait;
      const c = document.createElement('canvas'); c.width = c.height = 128;
      const g = c.getContext('2d');
      g.fillStyle = '#3a3f4d'; g.beginPath(); g.arc(64,64,64,0,Math.PI*2); g.fill();
      g.fillStyle = '#5b6174';
      g.beginPath(); g.arc(64,50,22,0,Math.PI*2); g.fill();
      g.beginPath(); g.ellipse(64,112,40,30,0,0,Math.PI*2); g.fill();
      return (blankPortrait = c);
    }

    function makeSmallURL(sq){
      const c = document.createElement('canvas'); c.width = c.height = 128;
      const g = c.getContext('2d'); g.imageSmoothingQuality = 'high';
      g.drawImage(sq, 0, 0, 128, 128);
      return c.toDataURL('image/jpeg', 0.72);
    }

    function setCustomPhoto(sq, select, persist){
      customPortrait = circularCanvas(sq, 200);
      customSmallURL = makeSmallURL(sq);
      if (persist){ try { localStorage.setItem(PHOTO_KEY, sq.toDataURL('image/jpeg', 0.86)); } catch(_) {} }
      refreshCustomOption();
      if (select) selectCustom(true);
    }
    function removeCustomPhoto(){
      customPortrait = null; customSmallURL = null;
      try { localStorage.removeItem(PHOTO_KEY); } catch(_) {}
      if (selectedSkin === 'custom'){
        selectedSkin = null;
        if (customOpt) customOpt.classList.remove('selected');
        pickImg.hidden = true; pickImg.removeAttribute('src');
      }
      refreshCustomOption();
      showToast('Foto eliminada', '#ffffff');
    }
    function selectCustom(fromEditor){
      if (!customPortrait || !customOpt) return;
      document.querySelectorAll('.skin-option').forEach(o => o.classList.remove('selected'));
      customOpt.classList.add('selected');
      selectedSkin = 'custom';
      playBtn.disabled = false;
      if (fromEditor){
        pickImg.src = customPortrait.toDataURL(); pickImg.hidden = false;
        skinPicker.classList.add('hidden');
        const fm = document.getElementById('formMsg'); if (fm) fm.textContent = '';
      }
    }
    function refreshCustomOption(){
      if (!customOpt) return;
      const img = customOpt.querySelector('.circ img');
      const has = !!customPortrait;
      customOpt.classList.toggle('has', has);
      if (has){ img.src = customPortrait.toDataURL(); img.hidden = false; }
      else { img.hidden = true; img.removeAttribute('src'); customOpt.classList.remove('selected'); }
      customOpt.querySelector('.lbl').textContent = has ? 'Mi foto' : 'Subir foto';
    }
    function buildCustomOption(){
      if (customOpt) return;
      const opt = document.createElement('div');
      opt.className = 'skin-option custom';
      opt.innerHTML =
        '<div class="circ"><img alt="" hidden>' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M4 8h3l1.5-2h7L17 8h3v11H4z"/><circle cx="12" cy="13" r="3.4"/></svg></div>' +
        '<button type="button" class="skin-badge edit" aria-label="Cambiar foto" title="Cambiar foto"><svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20h4L19 9l-4-4L4 16z"/></svg></button>' +
        '<button type="button" class="skin-badge del" aria-label="Quitar foto" title="Quitar foto"><svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg></button>' +
        '<span class="lbl">Subir foto</span>';
      opt.addEventListener('click', e => {
        if (!customPortrait){ e.__keepOpen = true; photoInput.click(); return; }
        selectCustom(false);
      });
      opt.querySelector('.edit').addEventListener('click', e => { e.stopPropagation(); photoInput.click(); });
      opt.querySelector('.del').addEventListener('click', e => { e.stopPropagation(); removeCustomPhoto(); });
      skinRow.appendChild(opt);
      customOpt = opt;
      refreshCustomOption();
    }

    // --- elegir archivo (cualquier tamaño) ---
    const PE_MAX_SIDE = 1600;   // se reduce a este lado para que el editor sea fluido
    function loadImgElement(url){
      return new Promise((resolve, reject) => {
        const im = new Image();
        im.onload = () => resolve(im);
        im.onerror = () => reject(new Error('decode'));
        im.src = url;
      });
    }
    async function loadPhotoFile(f){
      const url = URL.createObjectURL(f);
      try {
        const im = await loadImgElement(url);
        const w = im.naturalWidth, h = im.naturalHeight;
        if (!w || !h) throw new Error('empty');
        const big = Math.max(w, h);
        if (big <= PE_MAX_SIDE) return im;
        const sc = PE_MAX_SIDE/big;
        const rw = Math.max(1, Math.round(w*sc)), rh = Math.max(1, Math.round(h*sc));
        // 1) el navegador decodifica ya reducida (ahorra memoria con fotos gigantes)
        if (window.createImageBitmap){
          const tries = [
            { resizeWidth: rw, resizeHeight: rh, resizeQuality: 'high', imageOrientation: 'from-image' },
            { resizeWidth: rw, resizeHeight: rh, resizeQuality: 'high' }
          ];
          for (const opts of tries){
            try { return await createImageBitmap(f, opts); } catch(_) {}
          }
        }
        // 2) respaldo: reducir en pasos con un canvas
        let cur = im, cw = w, ch = h;
        while (Math.max(cw, ch) > PE_MAX_SIDE){
          const nw = Math.max(rw, Math.round(cw/2)), nh = Math.max(rh, Math.round(ch/2));
          const c = document.createElement('canvas'); c.width = nw; c.height = nh;
          const g = c.getContext('2d'); g.imageSmoothingQuality = 'high';
          g.drawImage(cur, 0, 0, nw, nh);
          cur = c; cw = nw; ch = nh;
        }
        return cur;
      } finally {
        setTimeout(() => URL.revokeObjectURL(url), 5000);
      }
    }
    photoInput.addEventListener('change', async () => {
      const f = photoInput.files && photoInput.files[0];
      photoInput.value = '';
      if (!f) return;
      if (f.type && !/^image\//.test(f.type)){ showToast('Elige un archivo de imagen', '#ff9a7a'); return; }
      showToast('Abriendo foto…', '#ffffff');
      try {
        const img = await loadPhotoFile(f);
        toastEl.classList.remove('show');
        peOpen(img);
      } catch(_) {
        showToast('No se pudo abrir esa imagen. Prueba con una JPG o PNG.', '#ff9a7a');
      }
    });

    // --- editor de recorte ---
    function peOpen(im){
      const src = im;
      const sw = src.naturalWidth || src.width, sh = src.naturalHeight || src.height;
      pe.img = src;
      pe.sw = sw; pe.sh = sh;
      pe.base = Math.max(PE_D/sw, PE_D/sh);
      pe.zoom = 1; pe.ox = 0; pe.oy = 0;
      peZoom.value = '1';
      photoEditor.classList.remove('hidden');
      peDraw();
    }
    function peClose(){ photoEditor.classList.add('hidden'); pe.img = null; peP.clear(); }
    function peClamp(){
      const w = pe.sw*pe.base*pe.zoom, h = pe.sh*pe.base*pe.zoom;
      const mx = Math.max(0, (w - PE_D)/2), my = Math.max(0, (h - PE_D)/2);
      pe.ox = Math.max(-mx, Math.min(mx, pe.ox));
      pe.oy = Math.max(-my, Math.min(my, pe.oy));
    }
    function peDraw(){
      if (!pe.img) return;
      const w = pe.sw*pe.base*pe.zoom, h = pe.sh*pe.base*pe.zoom;
      peCtx.clearRect(0, 0, PE_S, PE_S);
      peCtx.fillStyle = '#0b0b0b'; peCtx.fillRect(0, 0, PE_S, PE_S);
      peCtx.drawImage(pe.img, PE_S/2 + pe.ox - w/2, PE_S/2 + pe.oy - h/2, w, h);
      peCtx.save();
      peCtx.fillStyle = 'rgba(0,0,0,.62)';
      peCtx.beginPath(); peCtx.rect(0, 0, PE_S, PE_S); peCtx.arc(PE_S/2, PE_S/2, PE_D/2, 0, Math.PI*2, true);
      peCtx.fill('evenodd');
      peCtx.restore();
      peCtx.beginPath(); peCtx.arc(PE_S/2, PE_S/2, PE_D/2, 0, Math.PI*2);
      peCtx.lineWidth = 2; peCtx.strokeStyle = '#fff'; peCtx.stroke();
    }
    function peSetZoom(z){
      if (!pe.img) return;
      pe.zoom = Math.max(1, Math.min(4, z));
      peZoom.value = String(pe.zoom);
      peClamp(); peDraw();
    }
    function peRender(size){
      const c = document.createElement('canvas'); c.width = c.height = size;
      const g = c.getContext('2d'); g.imageSmoothingQuality = 'high';
      const k = size/PE_D;
      const w = pe.sw*pe.base*pe.zoom*k, h = pe.sh*pe.base*pe.zoom*k;
      g.fillStyle = '#2b2f3a'; g.fillRect(0, 0, size, size);
      g.drawImage(pe.img, size/2 + pe.ox*k - w/2, size/2 + pe.oy*k - h/2, w, h);
      return c;
    }
    const peP = new Map();
    peCanvas.addEventListener('pointerdown', e => {
      if (!pe.img) return;
      try { peCanvas.setPointerCapture(e.pointerId); } catch(_) {}
      peP.set(e.pointerId, { x:e.clientX, y:e.clientY });
    });
    peCanvas.addEventListener('pointermove', e => {
      if (!pe.img || !peP.has(e.pointerId)) return;
      const prev = peP.get(e.pointerId);
      const k = PE_S / peCanvas.getBoundingClientRect().width;
      if (peP.size === 1){
        pe.ox += (e.clientX - prev.x)*k; pe.oy += (e.clientY - prev.y)*k;
        peClamp(); peDraw();
        peP.set(e.pointerId, { x:e.clientX, y:e.clientY });
      } else if (peP.size === 2){
        const ids = [...peP.keys()];
        const other = peP.get(ids[0] === e.pointerId ? ids[1] : ids[0]);
        const d0 = Math.hypot(prev.x - other.x, prev.y - other.y);
        const d1 = Math.hypot(e.clientX - other.x, e.clientY - other.y);
        peP.set(e.pointerId, { x:e.clientX, y:e.clientY });
        if (d0 > 5) peSetZoom(pe.zoom*d1/d0);
      }
    });
    ['pointerup','pointercancel'].forEach(t => peCanvas.addEventListener(t, e => peP.delete(e.pointerId)));
    peCanvas.addEventListener('wheel', e => {
      if (!pe.img) return;
      e.preventDefault();
      peSetZoom(pe.zoom*(e.deltaY < 0 ? 1.08 : 0.926));
    }, { passive:false });
    peZoom.addEventListener('input', () => peSetZoom(parseFloat(peZoom.value)));
    document.getElementById('peCancel').addEventListener('click', peClose);
    document.getElementById('peOk').addEventListener('click', () => {
      if (!pe.img) return;
      const big = peRender(400);
      const sq = document.createElement('canvas'); sq.width = sq.height = 200;
      const sg = sq.getContext('2d'); sg.imageSmoothingQuality = 'high';
      sg.drawImage(big, 0, 0, 200, 200);
      peClose();
      setCustomPhoto(sq, true, true);
      showToast('¡Foto lista! Ya puedes jugar con tu cara', '#ffffff');
    });

    // foto guardada de otras veces
    try {
      const saved = localStorage.getItem(PHOTO_KEY);
      if (saved && saved.indexOf('data:image/jpeg') === 0){
        loadImage(saved).then(im => {
          const sq = document.createElement('canvas'); sq.width = sq.height = 200;
          sq.getContext('2d').drawImage(im, 0, 0, 200, 200);
          setCustomPhoto(sq, false, false);
        });
      }
    } catch(_) {}

    /* ===== Música de fondo de las pantallas de inicio ===== */
    const menuMusic = document.getElementById('menuMusic');
    menuMusic.volume = 0.4;
    (function(){
      const B64 = '';
      const bin = atob(B64), arr = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
      menuMusic.src = URL.createObjectURL(new Blob([arr], { type: 'audio/mpeg' }));
    })();
    function menuIsVisible(){
      return !running && !welcomeScreen.classList.contains('hidden') || !running && !startScreen.classList.contains('hidden');
    }
    let musicWanted = true;
    function playMenuMusic(){
      if (!menuMusic || !musicWanted) return;
      const p = menuMusic.play();
      if (p && p.catch) p.catch(() => {});
    }
    function stopMenuMusic(){
      if (!menuMusic) return;
      menuMusic.pause();
      menuMusic.currentTime = 0;
    }
    // Intenta sonar apenas carga; si el navegador lo bloquea, suena con el primer toque/clic/tecla
    playMenuMusic();
    ['pointerdown','touchstart','keydown','click'].forEach(ev => {
      window.addEventListener(ev, function unlock(e){
        if (e && e.target && e.target.closest && e.target.closest('.music-btn')) return;
        if (menuIsVisible() && menuMusic.paused) playMenuMusic();
        if (!menuMusic.paused) ['pointerdown','touchstart','keydown','click'].forEach(e2 => window.removeEventListener(e2, unlock, true));
      }, true);
    });

    // Avisos en pantalla si la música no puede sonar
    const musicMsg = document.getElementById('musicMsg');
    let musicMsgTimer = null;
    function showMusicMsg(t){
      musicMsg.textContent = t;
      musicMsg.style.display = 'block';
      clearTimeout(musicMsgTimer);
      musicMsgTimer = setTimeout(() => { musicMsg.style.display = 'none'; }, 12000);
    }
    function hideMusicMsg(){ musicMsg.style.display = 'none'; }
    menuMusic.addEventListener('playing', hideMusicMsg);
    menuMusic.addEventListener('error', () => {
      const c = menuMusic.error ? menuMusic.error.code : '?';
      showMusicMsg('No se pudo cargar la música (error ' + c + '). Es posible que tu navegador no soporte MP3.');
    });
    if (!menuMusic.canPlayType('audio/mpeg')) {
      showMusicMsg('Tu navegador no soporta audio MP3, por eso no suena la música.');
    }
    function tryPlayWithFeedback(){
      menuMusic.play().then(() => {
        setTimeout(() => {
          if (!menuMusic.paused && menuMusic.currentTime < 0.2) {
            showMusicMsg('El navegador no empezó a reproducir. Revisa que la pestaña no esté silenciada y el volumen del equipo.');
          }
        }, 1800);
      }).catch(err => {
        showMusicMsg('No suena: ' + (err && err.name ? err.name : 'error') + (err && err.message ? ' - ' + err.message : ''));
      });
    }

    // Botón para prender / apagar la música
    const musicBtns = document.querySelectorAll('.music-btn');
    function syncMusicBtns(){ musicBtns.forEach(b => b.classList.toggle('off', menuMusic.paused)); }
    menuMusic.addEventListener('play', syncMusicBtns);
    menuMusic.addEventListener('pause', syncMusicBtns);
    musicBtns.forEach(b => b.addEventListener('click', () => {
      if (menuMusic.paused) { musicWanted = true; tryPlayWithFeedback(); }
      else { musicWanted = false; menuMusic.pause(); }
      syncMusicBtns();
    }));
    syncMusicBtns();

    goSoloBtn.addEventListener('click', () => { ensureAudio(); sfxClick(); showForm(false); });
    goOnlineBtn.addEventListener('click', () => { ensureAudio(); sfxClick(); showForm(true); });
    backBtn.addEventListener('click', () => { sfxClick(); showWelcome(); });
    pickBtn.addEventListener('click', () => { sfxClick(); skinPicker.classList.remove('hidden'); });
    skinPicker.addEventListener('click', e => { if (e.target === skinPicker) skinPicker.classList.add('hidden'); });
    skinRow.addEventListener('click', e => {
      if (e.__keepOpen) return;
      if (!e.target.closest('.skin-option') || selectedSkin === null) return;
      pickImg.src = portraitFor(selectedSkin).toDataURL();
      pickImg.hidden = false;
      skinPicker.classList.add('hidden');
      document.getElementById('formMsg').textContent = '';
    });
  
    const exitBtn = document.getElementById('exitBtn');
    if (exitBtn){
      exitBtn.addEventListener('pointerdown', e => {
        e.preventDefault();
        e.stopPropagation();
        if (typeof endGame === 'function') endGame();
        else {
          running = false;
          document.getElementById('startScreen')?.classList.remove('hidden');
          document.getElementById('gameOverScreen')?.classList.add('hidden');
        }
        exitBtn.style.display = 'none';
      });
    }
  
   
    (function(){
      const joy = document.getElementById('mobileJoystick');
      if(!joy) return;
      const base = joy.querySelector('.joystick-base');
      const stick = joy.querySelector('.joystick-stick');
      if(!base || !stick) return;
  
      let active = false;
      let pointerId = null;
      let jx = 0, jy = 0;
  
      function updateFromPointer(e){
        const r = base.getBoundingClientRect();
        const cx = r.left + r.width * 0.5;
        const cy = r.top + r.height * 0.5;
        let dx = e.clientX - cx;
        let dy = e.clientY - cy;
  
        
        const max = Math.max(1, (r.width - stick.offsetWidth) * 0.5);
        const len = Math.hypot(dx, dy);
        if(len > max){
          dx = dx / len * max;
          dy = dy / len * max;
        }
  
        stick.style.transform = `translate3d(${dx}px,${dy}px,0)`;
        jx = dx / max;
        jy = dy / max;
      }
  
      function reset(){
        active = false;
        pointerId = null;
        jx = 0;
        jy = 0;
        stick.style.transform = 'translate3d(0,0,0)';
      }
  
      base.addEventListener('pointerdown', e => {
        if(active) return;
        active = true;
        pointerId = e.pointerId;
        try { base.setPointerCapture(e.pointerId); } catch(_) {}
        updateFromPointer(e);
        e.preventDefault();
        e.stopPropagation();
      }, {passive:false});
  
      base.addEventListener('pointermove', e => {
        if(!active || e.pointerId !== pointerId) return;
        updateFromPointer(e);
        e.preventDefault();
      }, {passive:false});
  
      base.addEventListener('pointerup', e => {
        if(e.pointerId === pointerId) reset();
      });
      base.addEventListener('pointercancel', e => {
        if(e.pointerId === pointerId) reset();
      });
      base.addEventListener('lostpointercapture', () => {
        if(active) reset();
      });
  
      window.addEventListener('blur', reset);
  
      window.nebulosaJoystick = {
        get x(){ return jx; },
        get y(){ return jy; },
        get active(){ return active; }
      };
    })();
  
  })();
